/** Le varianti selezionabili, nell'ordine in cui ha senso mostrarle. */
export const MV_ICON_VARIANTS = [
  { id: 'bold-duotone', label: 'Bold Duotone', note: 'piena, con campitura tenue' },
  { id: 'bold', label: 'Bold', note: 'piena, un solo colore' },
  { id: 'outline', label: 'Outline', note: 'contorno come forma piena' },
  { id: 'linear', label: 'Linear', note: 'tratto sottile' },
  { id: 'line-duotone', label: 'Line Duotone', note: 'tratto con campitura' },
  { id: 'broken', label: 'Broken', note: 'tratto interrotto' },
] as const;

export type MvIconVariant = (typeof MV_ICON_VARIANTS)[number]['id'];

/** I nomi che Obsidian disegna PRIMA che i plugin carichino. Lo snippet CSS
 *  copre questi: sono gli unici che altrimenti si vedrebbero cambiare. */
const BOOT_NAMES = ["chevron-right","chevron-left","search","plus","chevrons-up-down","grip-vertical","link","menu","bold","italic","strikethrough","highlighter","code","code-2","heading-1","heading-2","heading-3","quote","list","list-ordered","list-checks","message-square","file-symlink","remove-formatting","wand-2"];

/** Costruisce lo snippet CSS di boot per una variante.
 *
 *  Generato dagli stessi dati del registry invece di essere una stringa a
 *  parte: un CSS statico bundlato accanto alle tabelle direbbe la stessa cosa
 *  due volte, e cambiando variante ne resterebbe una indietro.
 *
 *  Serve perché uno snippet è applicato con il TEMA, prima di qualsiasi
 *  plugin: queste icone sono giuste dal primo fotogramma, invece di cambiare
 *  qualche secondo dopo. Ed essendo CSS non tocca il DOM, quindi non può
 *  rompere il controllo che le contiene. */
export function buildBootCss(variant?: string): string {
  const alt = variant ? (VARIANT_PATHS[variant] ?? {}) : {};
  const rules: string[] = [];
  for (const name of BOOT_NAMES) {
    const glyph = alt[name] ?? PATHS[name];
    if (!glyph) continue;
    const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24">${glyph}</svg>`
      .replace(/"/g, '%22')
      .replace(/#/g, '%23')
      .replace(/</g, '%3C')
      .replace(/>/g, '%3E')
      .replace(/&/g, '%26');
    const url = `url("data:image/svg+xml,${svg}") center / contain no-repeat`;
    // Due grafie: Obsidian marca le proprie icone con `lucide-<nome>`, quelle
    // registrate via addIcon con il nome nudo. `:not(:has(...))` limita la
    // maschera a ciò che il plugin non ha ancora convertito, così le due non
    // si sovrappongono mai.
    const not = ':not(:has(g[data-mv-icon]))';
    const sel = `.svg-icon.lucide-${name}${not},.svg-icon.${name}${not}`;
    rules.push(
      `${sel}{background-color:currentColor;-webkit-mask:${url};mask:${url}}`,
      `${sel}>*{display:none}`,
    );
  }
  const NL = String.fromCharCode(10);
  const header =
    `/* mv-icons [${MV_ICON_SET}] — GENERATO dal plugin, non editare a mano.` +
    NL +
    `   Copre le ${BOOT_NAMES.length} icone disegnate prima che i plugin carichino. */`;
  return [header, ...rules, ''].join(NL);
}

/** Identifica set e variante di questo snippet, così il plugin sa se il file
 *  su disco è da riscrivere senza confrontarne il contenuto. */
export const MV_ICON_SET = 'solar';

/** Registra ogni glifo nel registry di Obsidian. Va chiamata una sola volta,
 *  prima che qualunque view renderizzi. Non è reversibile a runtime.
 *
 *  `variant` sostituisce il glifo dove una variante alternativa esiste; per
 *  gli altri nomi resta quello di base. I nomi con una variante forzata — i
 *  chevron, il menu — la mantengono comunque: sono scelte di leggibilità a
 *  una misura precisa, non parte dello stile generale. */
export function installMvIcons(variant?: string): void {
  const alt = variant ? (VARIANT_PATHS[variant] ?? {}) : {};
  for (const [name, d] of Object.entries(PATHS)) addIcon(name, body(alt[name] ?? d));
}

/** Ridisegna le icone GIÀ presenti nel DOM che ora hanno un glifo nostro.
 *
 *  Serve perché `addIcon()` aggiorna il registry ma mai il DOM: qualunque
 *  icona disegnata prima di `installMvIcons()` resterebbe al glifo Lucide per
 *  tutta la sessione. Riguarda il chrome costruito all'avvio — ribbon, tab bar,
 *  view header — e le icone dei plugin che si caricano prima di questo.
 *
 *  Riconoscere quali ridipingere: Obsidian scrive il nome dell'icona come
 *  classe sull'SVG — `lucide-archive` per le sue, il nome nudo (`hi-calendar`)
 *  per quelle registrate via addIcon. Un glifo già nostro porta
 *  `data-mv-icon`, quindi viene saltato: la funzione è idempotente e non
 *  ricade su se stessa.
 *
 *  Guardare solo le `lucide-*` non basta. Le icone che gli altri plugin
 *  registrano con un nome proprio vengono disegnate quando costruiscono la
 *  ribbon, e se quel plugin carica prima di questo il bottone resta al glifo
 *  vecchio per sempre — invisibile a un filtro sulle Lucide.
 *
 *  L'SVG viene sostituito, non ridisegnato sul parent: `setIcon(parent, …)`
 *  svuoterebbe il contenitore, e molti di questi parent contengono anche la
 *  label del bottone.
 *
 *  @returns quante icone sono state sostituite. */
export function refreshRenderedIcons(root: ParentNode = document): number {
  if (typeof (root as Element).querySelectorAll !== 'function') return 0;
  const candidates = root.querySelectorAll<SVGElement>('svg.svg-icon');
  if (!candidates.length) return 0;

  const scratch = document.createElement('div');
  let replaced = 0;
  for (const svg of Array.from(candidates)) {
    if (svg.querySelector('g[data-mv-icon]')) continue; // già nostro
    // La classe è `svg-icon <nome>`, con `lucide-` davanti per le native.
    const name = (svg.getAttribute('class') ?? '')
      .split(/\s+/)
      .map((c) => (c.startsWith('lucide-') ? c.slice('lucide-'.length) : c))
      .find((c) => c !== 'svg-icon' && c in PATHS);
    if (!name) continue;
    scratch.empty();
    setIcon(scratch, name);
    const fresh = scratch.firstElementChild;
    if (!fresh || !fresh.querySelector('g[data-mv-icon]')) continue;
    svg.replaceWith(fresh);
    replaced += 1;
  }
  return replaced;
}

